import { useMemo } from "react";

export function TimezoneSelector({
  utcHour = {{utcHour}},
  utcMinute = {{utcMinute}},
  timezone = "{{timezone}}",
  accent = "{{accent}}",
}) {
  const value = useMemo(() => {
    const d = new Date(Date.UTC(2026, 0, 15, utcHour, utcMinute));
    return new Intl.DateTimeFormat("en-GB", { timeZone: timezone, hour: "2-digit", minute: "2-digit", weekday: "short" }).format(d);
  }, [utcHour, utcMinute, timezone]);
  return (
    <div style={{ font: "14px/1.5 system-ui, sans-serif", color: "#241430", background: "#FAF7F2", padding: 20, borderRadius: 12, width: 280, boxSizing: "border-box" }}>
      <p style={{ margin: "0 0 4px", fontSize: 11, color: "#24143099" }}>{utcHour}:{utcMinute} UTC in&hellip;</p>
      <p style={{ margin: "0 0 12px", fontFamily: "ui-monospace, monospace", fontWeight: 700, fontSize: 13, color: accent }}>{timezone}</p>
      <p style={{ margin: 0, fontSize: 24, fontWeight: 800 }}>{value}</p>
    </div>
  );
}
